SET time_zone='+00:00',lock_wait_timeout=5,innodb_lock_wait_timeout=5,MAX_EXECUTION_TIME=5000;
SELECT t.id task_id,t.subject_id meeting_id,t.input_id,t.state task_state,t.last_error,e.id execution_id,e.operation_id,e.state execution_state,e.request_hash,e.task_attempt,o.state operation_state,o.external_result_id,o.reconcile_epoch,o.reconcile_owner,o.reconcile_expires_at,r.id permit_id,r.settled_at FROM durable_task t JOIN external_execution e ON e.task_id=t.id JOIN external_operation o ON o.id=e.operation_id LEFT JOIN model_reservation r ON r.execution_id=e.id WHERE t.id IN ('5371fac5-6674-499f-9187-4505749e93f1','fc5cc42c-d03d-4363-8b4d-8d4e5e87d638');
